  ) as v(route_code, old_name, new_name, registration_number, occupation,
         institution, district, region, phone)
)
update trainees t set
  name                = f.new_name,
  registration_number = coalesce(f.registration_number, t.registration_number),
  occupation          = f.occupation,
  institution         = f.institution,
  district            = f.district,
  region              = f.region,
  phone               = f.phone
from final_roster f
join routes r on r.code = f.route_code
where t.route_id = r.id
  and t.name = f.old_name
  and t.track = 'TP'
  and (
    t.name                is distinct from f.new_name
    or t.registration_number is distinct from coalesce(f.registration_number, t.registration_number)
    or t.occupation       is distinct from f.occupation
    or t.institution      is distinct from f.institution
    or t.district         is distinct from f.district
    or t.region           is distinct from f.region
    or t.phone            is distinct from f.phone
  );

-- ── NOTE 1: the Pato Mohele pair is still unresolved ───────────────────
-- The register carries RAFAEL PATO MOHELE and RAPHAEL PATO MOHELE on Route 2
-- as two rows sharing ONE registration number, MVTTC/CAVT/2025/0128, with two
-- different e-mail addresses (raphaelpato89@ and raphaelpato261@). The FINAL
-- VERSION did not fix this; it made it sharper, since the original at least
-- left one of the two registration numbers blank.
--
-- trainees.registration_number is UNIQUE, so both rows cannot hold it. This
-- migration therefore leaves RAPHAEL's registration number null, exactly as
-- 0008 left it, rather than failing on the constraint. The College must say
-- whether these are two people or one entered twice. If one, the duplicate row
-- must be removed by a Super Admin -- NOT by this migration: a trainee delete
-- cascades to assessment_marks, and by then one of the two rows may carry a
-- real assessment.

